import { test as base, expect } from '@playwright/test';
import fs from 'node:fs';

// Chromium with a fake microphone (a tone, so totalAudioEnergy > 0) that
// trusts exactly the server certificate generated by the selfca setup.
const test = base.extend({
  browser: [
    async ({ playwright }, use) => {
      const browser = await playwright.chromium.launch({
        args: [
          '--use-fake-ui-for-media-stream',
          '--use-fake-device-for-media-stream',
          '--allow-loopback-in-peer-connection', // ADVERTISE_IPS=127.0.0.1
          '--autoplay-policy=no-user-gesture-required',
          `--ignore-certificate-errors-spki-list=${process.env.TINCAN_SPKI}`,
        ],
      });
      await use(browser);
      await browser.close();
    },
    { scope: 'worker' },
  ],
});

const base_url = () => process.env.TINCAN_BASE_URL;

// TINCAN_E2E_MIC=synthetic replaces getUserMedia with a WebAudio oscillator.
// Use it where Chrome's capture stack is unavailable (e.g. a macOS sandbox
// without access to the audio/TCC services, where even the fake device
// hangs). Everything after capture — WebRTC, signaling, the SFU — is real.
const synthetic = process.env.TINCAN_E2E_MIC === 'synthetic';

async function newCallContext(browser) {
  const ctx = await browser.newContext({ permissions: ['microphone'] });
  if (synthetic) {
    await ctx.addInitScript(() => {
      navigator.mediaDevices.getUserMedia = async () => {
        const ac = new AudioContext();
        const osc = ac.createOscillator();
        const dst = ac.createMediaStreamDestination();
        osc.frequency.value = 440;
        osc.connect(dst);
        osc.start();
        return dst.stream;
      };
    });
  }
  return ctx;
}

// inboundAudio returns [{packets, energy}] for every inbound audio stream.
async function inboundAudio(page) {
  return page.evaluate(async () => {
    const pc = window.tincan?.call?.pc;
    if (!pc) return [];
    const out = [];
    (await pc.getStats()).forEach((s) => {
      if (s.type === 'inbound-rtp' && s.kind === 'audio') {
        out.push({ packets: s.packetsReceived || 0, energy: s.totalAudioEnergy || 0 });
      }
    });
    return out;
  });
}

// expectHearing waits until the page receives audio with growing packet
// counts and non-zero energy.
async function expectHearing(page, label) {
  let first = null;
  await expect
    .poll(
      async () => {
        const streams = await inboundAudio(page);
        const best = streams.reduce((a, s) => (s.packets > (a?.packets ?? -1) ? s : a), null);
        if (!best || best.packets === 0) return 'no packets';
        if (!first) {
          first = best;
          return 'waiting for growth';
        }
        if (best.packets <= first.packets) return `packets not growing (${best.packets})`;
        if (!(best.energy > 0)) return `no audio energy (packets ${best.packets})`;
        return 'ok';
      },
      { message: `${label} should receive audio`, timeout: 15_000, intervals: [500] },
    )
    .toBe('ok');
}

async function joinAudio(page, name) {
  await page.fill('#name', name);
  await page.click('#join');
  await expect(page.locator('#in-call')).toBeVisible();
}

test('two browsers hear each other; leaving updates the list', async ({ browser }) => {
  const ctxA = await newCallContext(browser);
  const ctxB = await newCallContext(browser);
  const a = await ctxA.newPage();
  const b = await ctxB.newPage();
  for (const [p, n] of [[a, 'A'], [b, 'B']]) {
    p.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') console.log(`[${n}] ${m.text()}`); });
  }

  // Create in A, join from B.
  await a.goto(base_url() + '/');
  await a.click('#create');
  await a.waitForURL(/\/room\/[a-z2-7]{26}$/);
  const roomURL = a.url();
  await b.goto(roomURL);
  await expect(b.locator('#join')).toBeVisible();

  await joinAudio(a, 'Alice');
  await joinAudio(b, 'Bob');

  await expect(a.locator('#participants li')).toHaveCount(2);
  await expect(b.locator('#participants li')).toHaveCount(2);
  await expect(a.locator('#participants')).toContainText('Bob');

  await expectHearing(a, 'Alice');
  await expectHearing(b, 'Bob');
  await expect(a.locator('#status')).toContainText(/Audio: (connected|completed)/);

  // Leave in B → A's list shrinks; B is back home.
  await b.click('#leave');
  await b.waitForURL(base_url() + '/');
  await expect(a.locator('#participants li')).toHaveCount(1, { timeout: 10_000 });
  await expect(a.locator('#participants')).not.toContainText('Bob');

  await ctxA.close();
  await ctxB.close();
});

test('unknown room shows not found', async ({ browser }) => {
  const page = await (await browser.newContext()).newPage();
  await page.goto(base_url() + '/room/aaaaaaaaaaaaaaaaaaaaaaaaaa');
  await expect(page.locator('#notfound')).toBeVisible();
});

test.afterAll(() => {
  const log = process.env.TINCAN_SERVER_LOG;
  if (log && fs.existsSync(log) && test.info().status !== 'passed') {
    console.log(fs.readFileSync(log, 'utf8').split('\n').slice(-40).join('\n'));
  }
});
